layoutPanels582=function(){if(!WEB580)return;const grid=document.getElementById('web-dashboard573');if(!grid)return;const cards=panels583().sort((a,b)=>Number(a.style.order)-Number(b.style.order));const columns=Math.max(1,getComputedStyle(grid).gridTemplateColumns.split(/\s+/).filter(Boolean).length),heights=Array(columns).fill(1);cards.forEach((el,i)=>{const col=i%columns;el.classList.add('wall-panel582');el.style.setProperty('grid-column',String(col+1),'important');el.style.setProperty('grid-row-start',String(heights[col]),'important');const span=Math.ceil(el.getBoundingClientRect().height+20);el.style.setProperty('grid-row-end','span '+Math.max(1,span),'important');heights[col]+=Math.max(1,span);});};
function trainingRank592(i){const value=Number(c().skills[i]||0);return value>=2?'expert':value>=1?'trained':value>0||skillRules().jack?'half':'none';}
