const defenseBefore592=defenseBody510;defenseBody510=function(){const box=document.createElement('div');box.innerHTML=defenseBefore592();const en=SETTINGS48.language==='en';if(en){for(const option of box.querySelectorAll('option'))option.textContent=option.textContent.replace(/sem (proficiência|PROFICIENCY)/gi,'not proficient');const walk=document.createTreeWalker(box,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode())node.textContent=node.textContent.replace(/equipad[oa]:/gi,'Equipped:');}const crest=box.querySelector('.defense-shield-label512');if(crest)crest.textContent=text554('Classe de Armadura','Armor Class');const label=box.querySelector('.shield-magic512');if(label){for(const node of label.childNodes)if(node.nodeType===3)node.textContent=text554('Bônus mágico do escudo','Shield magic bonus');label.querySelector('input')?.setAttribute('aria-label',text554('Bônus mágico do escudo','Shield magic bonus'));const small=label.querySelector('small');if(small)small.textContent=text554('O escudo comum concede +2 CA. Este valor é somado quando o escudo está equipado e a CA é automática. Na CA manual, informe o valor final completo.','A standard shield grants +2 AC. This bonus is added when the shield is equipped and AC is calculated automatically. For manual AC, enter AC including all bonuses.');}for(const p of box.querySelectorAll('p'))if(/proficiência é verificada|PROFICIENCY é verificada/i.test(p.textContent))p.textContent=text554('A proficiência é verificada automaticamente. Confira requisitos de Força, estilos e efeitos especiais.','Proficiency is checked automatically. Check Strength requirements, fighting styles, and special effects.');return box.innerHTML;};
openPassives517=function(){const first=[13,9,8],indices=[...first,...SKILLS.map((_,i)=>i).filter(i=>!first.includes(i))];openPlayDialog(text554('Perícias passivas','Passive Skills'),`<p class="muted">${text554('Valores passivos: 10 + bônus da perícia, incluindo proficiência, Expertise e bônus específicos da ficha. Conforme a situação, vantagem acrescenta 5 e desvantagem reduz 5.','Passive scores: 10 + the skill modifier, including proficiency, expertise, and character-specific bonuses. Depending on the situation, advantage adds 5 and disadvantage subtracts 5.')}</p><div class="passive-list517">${indices.map(i=>`<div class="passive-row517"><span>${esc(SETTINGS48.language==='en'?phrase550(SKILLS[i][0],true):SKILLS[i][0])}<small>${text554('Valor passivo','Passive score')}</small></span><b>${10+skillBonus(i)}</b></div>`).join('')}</div>`);};
